mapper.select:
SELECT COUNT(recent.id)
FROM (SELECT a.id
      FROM login_attempts a
      WHERE a.kind = 'LOGIN'
        AND a.result = 'FAILURE'
        AND a.login_key_hash = #{loginKeyHash}
        AND a.client_ip = #{clientIp}
        AND a.attempted_at > #{since}
      ORDER BY a.attempted_at DESC, a.id DESC
      LIMIT #{cap}) recent

mapper.delete:
DELETE FROM login_attempts
WHERE kind = 'LOGIN'
  AND result = 'FAILURE'
  AND login_key_hash = #{loginKeyHash}
  AND client_ip = #{clientIp}

DELETE FROM login_attempts
WHERE kind = 'LOGIN'
  AND login_key_hash = #{loginKeyHash}
